insert into public.places (id, status, area, kind, depth, name_vi, name_en, name_vi_short, lat, lng, address, opening_hours, themes, tags, visit_min, price_min_k, price_max_k, price_checked_on, tone, blurb_vi, blurb_en, story_vi, story_en, why_vi, why_en, photo_tip_vi, photo_tip_en, etiquette_vi, etiquette_en, challenge_vi, challenge_en, option1_vi, option1_en, option2_vi, option2_en, option3_vi, option3_en, hint_vi, hint_en, answer, wikidata, sources, review_notes) values
  ('ngoc-son', 'approved', 'hoan-kiem', 'sight', 'full', 'Đền Ngọc Sơn', 'Ngoc Son Temple', 'Đền Ngọc Sơn', 21.0307, 105.8524, null, null, array['culture','history','photo']::text[], array['iconic','groups']::text[], 20, 30, 30, null, 'brick', 'Bước qua cây cầu đỏ để vào câu chuyện giữa lòng hồ.', 'Cross the red bridge into a story at the heart of the lake.', 'Đền nằm trên đảo Ngọc giữa hồ. Diện mạo ngày nay có từ những năm 1860, khi nhà nho Nguyễn Văn Siêu tu sửa và dựng thêm Tháp Bút, Đài Nghiên ở cổng. Trong đền thờ Văn Xương – vị thần văn chương – và Hưng Đạo Đại Vương Trần Quốc Tuấn, người ba lần đánh thắng quân Nguyên Mông. Đến nay học trò vẫn tới đây cầu may trước kỳ thi.', 'The temple sits on Jade Island in the lake. Its present form dates from the 1860s, when the scholar Nguyen Van Sieu restored it and added the Pen Tower and Ink Slab at the gate. Inside, people honour Van Xuong, the god of literature, and the general Tran Hung Dao, who defeated the Mongol armies. Students still come here to pray before exams.', 'Vì sao lại có tháp hình ngọn bút? Trên tháp khắc “Tả Thanh Thiên” – viết lên trời xanh – ước vọng lớn của người đi học.', 'Why a brush-shaped tower? It says “write on the blue sky” — a scholar’s wish for great ambition, carved in stone.', 'Đứng trên phố Đinh Tiên Hoàng, lệch về phía nam cổng đền, để lấy trọn cầu đỏ và mái đền trong một khung.', 'Stand on Dinh Tien Hoang street, just south of the gate, to fit the red bridge and the temple roof in one frame.', 'Mặc kín vai và gối, nói nhỏ, không chỉ tay vào ban thờ. Chụp ảnh thoải mái ở ngoài chính điện.', 'Cover shoulders and knees, speak softly, and don’t point at the altars. Photos are fine outside the main shrine.', 'Ở cổng có ngọn tháp đá hình cây bút. Ba chữ trên tháp có nghĩa là gì?', 'At the gate stands a stone tower shaped like a writing brush. What do the three characters on it mean?', 'Viết lên trời xanh', 'Write on the blue sky', 'Thiên hạ thái bình', 'Peace under heaven', 'Vạn thọ vô cương', 'Ten thousand years of life', 'Hãy nghĩ tới cây bút và một tờ giấy thật lớn trên đầu bạn.', 'Think of a brush and a very big sheet of paper above you.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('ma-may-87', 'approved', 'hoan-kiem', 'sight', 'full', 'Nhà cổ 87 Mã Mây', 'Heritage House 87 Ma May', 'Nhà cổ 87 Mã Mây', 21.0345, 105.8538, null, null, array['culture','history','rainy']::text[], array['quiet','cultural']::text[], 25, 10, 10, null, 'butter', 'Bước vào nhịp sống của một ngôi nhà buôn phố cổ.', 'Step into the rhythm of an Old Quarter merchant home.', 'Đây là kiểu “nhà ống” điển hình: mặt tiền hẹp, lòng nhà rất sâu. Ngày xưa thuế tính theo bề ngang mặt phố nên người buôn bán xây nhà dài và hẹp – trước là cửa hàng, sau là chỗ ở. Ngôi nhà có từ cuối thế kỷ 19, được trùng tu năm 1999 để kể lại cách một gia đình phố cổ sống và buôn bán.', 'This is a classic “tube house”: narrow at the street, very deep inside. Shops were taxed by the width of their frontage, so merchants built long and thin — shop in front, family behind. The house dates from the late 19th century and was restored in 1999 to show how an Old Quarter family lived and traded.', 'Vì sao giữa nhà có khoảng sân trống? Nhà sâu như vậy, đó là cách duy nhất để lấy ánh sáng, gió và nước mưa vào trong.', 'Why the open courtyard in the middle? In a house this deep, it’s the only way to get light, air and rainwater inside.', 'Đứng ở khoảng sân thứ nhất, chụp hắt lên ban công gỗ – ánh sáng dịu rơi từ khoảng trời trống.', 'From the first courtyard, shoot up toward the wooden balcony — soft light falls from the open sky.', 'Đi nhẹ trên sàn gỗ cũ và không ngồi lên đồ trưng bày.', 'Walk gently on the old wooden floors and don’t sit on displayed furniture.', 'Thứ gì giúp ánh sáng và gió vào được giữa ngôi nhà dài này?', 'What lets light and air reach the middle of this long house?', 'Giếng trời', 'An open-sky courtyard', 'Mái kính', 'A glass roof', 'Cửa sổ lớn phía sau', 'Big back windows', 'Hãy ngước lên khi bạn tới khoảng trống đầu tiên.', 'Look up when you reach the first open space.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('bach-ma', 'approved', 'hoan-kiem', 'sight', 'full', 'Đền Bạch Mã', 'Bach Ma Temple', 'Đền Bạch Mã', 21.0368, 105.8518, null, null, array['culture','history']::text[], array['quiet','free']::text[], 20, 0, 20, null, 'teal', 'Con ngựa trắng chỉ đường cho nhà vua đắp thành Thăng Long.', 'The white horse that showed a king where to build his city walls.', 'Tương truyền khi vua Lý Thái Tổ dời đô về Thăng Long năm 1010, thành đắp mãi vẫn đổ. Vua đến đây cầu khấn thì thấy một con ngựa trắng hiện ra, chạy vòng quanh kinh thành. Vua cho đắp thành theo vết chân ngựa và thành đứng vững. Đền trở thành trấn phía Đông trong Thăng Long tứ trấn.', 'Legend says that when King Ly Thai To moved the capital to Thang Long in 1010, his walls kept collapsing. He prayed here, and a white horse appeared and trotted a path around the city. The king built along its hoofprints and the walls held. The temple became the eastern guardian of the four that protect the old capital.', 'Vì sao huyền thoại lớn mà đền lại nhỏ? Đất phố cổ chật hẹp – ngôi đền phát triển vào trong chứ không lan ra ngoài.', 'Why is it so small for such a big legend? Old Quarter plots were tiny — the temple grew inward, not outward.', 'Đứng ở cửa, lấy những hàng cột sơn son dẫn mắt người xem vào ban thờ.', 'From the doorway, frame the red lacquered pillars leading your eye to the altar.', 'Mặc kín vai và gối, nói nhỏ, không chỉ tay vào ban thờ. Chụp ảnh thoải mái ở ngoài chính điện.', 'Cover shoulders and knees, speak softly, and don’t point at the altars. Photos are fine outside the main shrine.', 'Theo truyền thuyết, con ngựa trắng đã chỉ cho nhà vua điều gì?', 'According to the legend, what did the white horse show the king?', 'Nơi đắp thành', 'Where to build the city walls', 'Nơi đào hồ', 'Where to dig a lake', 'Nơi quân giặc ẩn náu', 'Where the enemy was hiding', 'Thành đắp mãi vẫn đổ…', 'The walls kept falling down…', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('water-puppets', 'approved', 'hoan-kiem', 'sight', 'full', 'Nhà hát Múa rối nước Thăng Long', 'Thang Long Water Puppets', 'Múa rối nước Thăng Long', 21.0318, 105.8535, null, null, array['culture','rainy']::text[], array['iconic','indoor','groups']::text[], 50, 100, 150, null, 'leaf', 'Tích trò đồng quê diễn trên mặt nước cùng nhạc cụ dân tộc.', 'Rice-field folk tales performed on water, with live music.', 'Múa rối nước ra đời trên những cánh đồng ngập nước vùng châu thổ sông Hồng từ gần một nghìn năm trước. Nghệ nhân đứng ngâm nửa người trong nước sau bức mành tre, điều khiển con rối gỗ bằng sào dài giấu dưới mặt nước. Mở màn luôn là chú Tễu – cậu bé làng tinh nghịch dẫn dắt từng tích trò.', 'Water puppetry began in the flooded rice fields of the Red River Delta almost a thousand years ago. Puppeteers stand waist-deep in water behind a bamboo screen and move carved wooden figures with long poles hidden underwater. The show opens with Chu Teu, a cheeky village boy who introduces every scene.', 'Vì sao lại diễn trên nước? Mặt nước giấu đi sào và máy móc, khiến con rối như tự chuyển động.', 'Why water? It hides the rods and machinery, so the puppets seem to move on their own.', 'Không dùng đèn flash. Ngồi lùi vài hàng và chờ màn rồng phun lửa, phun nước.', 'No flash. Sit a few rows back and wait for the dragons — they breathe fire and spray water.', 'Đến sớm 15 phút vì suất diễn bắt đầu đúng giờ. Để điện thoại im lặng khi xem.', 'Arrive 15 minutes early; shows start on time. Keep phones silent during the performance.', 'Con rối tinh nghịch mở màn buổi diễn là ai?', 'Who is the cheeky puppet who opens the show?', 'Chú Tễu', 'Chu Teu', 'Thánh Gióng', 'Thanh Giong', 'Sơn Tinh', 'Son Tinh', 'Cậu bé làng bụng tròn, cười toe toét.', 'He’s a round-bellied village boy with a big grin.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('cathedral', 'approved', 'hoan-kiem', 'sight', 'full', 'Nhà thờ Lớn Hà Nội', 'St. Joseph''s Cathedral', 'Nhà thờ Lớn', 21.0287, 105.849, null, null, array['culture','photo','history']::text[], array['free','photo']::text[], 15, 0, 0, null, 'brick', 'Tháp chuông tân gothic bên quảng trường trà chanh vỉa hè.', 'Neo-gothic towers above a square full of lemon-tea stools.', 'Hoàn thành năm 1886, nhà thờ là một trong những công trình đầu tiên của Hà Nội thời Pháp. Hai tháp chuông được mô phỏng theo Nhà thờ Đức Bà Paris. Nhà thờ được xây trên nền chùa Báo Thiên cổ đã bị phá bỏ. Ngày nay quảng trường phía trước là chỗ giới trẻ Hà Nội ngồi ghế nhựa uống trà chanh.', 'Completed in 1886, the cathedral was one of the first buildings of French colonial Hanoi. Its twin bell towers were modelled on Notre-Dame de Paris. It stands on the site of the ancient Bao Thien pagoda, which was demolished to make way for it. Today the square in front is where young Hanoians sit on tiny stools with iced lemon tea.', 'Vì sao nhà thờ trông sẫm màu? Mặt tiền không sơn – hàng chục năm mưa nắng nhiệt đới phủ lên lớp rêu xám ấy.', 'Why does it look so dark? The facade was left unpainted — decades of tropical rain gave it that grey patina.', 'Sang quán trà chanh góc phố Nhà Chung và chụp hất lên – vừa đủ hai tháp chuông và con phố phía trước.', 'Cross to the lemon-tea stalls on the corner of Nha Chung and shoot upward — both towers fit with the street in front.', 'Nhà thờ vẫn làm lễ: chỉ vào trong giờ mở cửa và giữ yên lặng khi có thánh lễ.', 'It is an active church: enter only during open hours and stay quiet during Mass.', 'Hai tháp chuông được lấy cảm hứng từ nhà thờ nổi tiếng nào?', 'Which famous church inspired the twin towers?', 'Nhà thờ Đức Bà Paris', 'Notre-Dame de Paris', 'Vương cung thánh đường Thánh Phêrô, Rome', 'St. Peter''s in Rome', 'Nhà thờ lớn Cologne', 'Cologne Cathedral', 'Những người thiết kế là người Pháp.', 'The architects were French.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('women-museum', 'approved', 'hoan-kiem', 'sight', 'full', 'Bảo tàng Phụ nữ Việt Nam', 'Vietnamese Women''s Museum', 'Bảo tàng Phụ nữ Việt Nam', 21.0237, 105.8513, null, null, array['culture','history','rainy']::text[], array['indoor','cultural']::text[], 45, 40, 40, null, 'teal', 'Người bán hàng, người mẹ, người lính — Việt Nam qua câu chuyện phụ nữ.', 'Market traders, mothers and soldiers — Vietnam told through women.', 'Bốn tầng trưng bày theo chân người phụ nữ Việt qua gia đình, lịch sử và thời trang. Một phòng được yêu thích nhất kể về những người bán hàng rong Hà Nội – các chị từ làng ven đô vào phố từ tờ mờ sáng, gánh hoa quả, hoa tươi, quà vặt, dành dụm gửi về nuôi con.', 'Four floors follow Vietnamese women through family life, history and fashion. One of the most loved rooms is about Hanoi’s street vendors — women who walk in from nearby villages before dawn, carrying fruit, flowers and snacks on a bamboo shoulder pole, and send their earnings home to their children.', 'Vì sao lại là đòn gánh? Nó giữ thăng bằng hai quang hàng nặng và giúp người đi len lỏi qua phố nhỏ.', 'Why a shoulder pole? It balances two heavy baskets and leaves the walker free to weave through narrow streets.', 'Bức tường hàng rong ở tầng trệt rất hợp để chụp ảnh nhóm.', 'The ground-floor street-vendor wall is great for a group photo.', 'Một số câu chuyện rất xúc động – hãy đọc lặng lẽ và nhường người khác thời gian.', 'Some personal stories are painful — read quietly and let others take their time.', 'Trong phòng hàng rong, các chị mang hàng bằng gì?', 'In the street-vendor room, what do the women carry their goods with?', 'Đòn gánh', 'A bamboo shoulder pole', 'Xe đẩy', 'A push cart', 'Ba lô', 'A backpack', 'Hai cái quang, một thanh tre dài.', 'Two baskets, one long stick.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('hoa-lo', 'approved', 'hoan-kiem', 'sight', 'full', 'Di tích Nhà tù Hỏa Lò', 'Hoa Lo Prison Relic', 'Nhà tù Hỏa Lò', 21.0254, 105.8465, null, null, array['history','rainy']::text[], array['history','indoor']::text[], 45, 50, 50, null, 'butter', 'Một thế kỷ Hà Nội sau những bức tường, từ thời thuộc địa đến chiến tranh.', 'A century of Hanoi in one set of walls, from colonial cells to war.', 'Người Pháp xây nhà tù năm 1896 trên đất làng gốm Phụ Khánh – “hỏa lò” nghĩa là lò lửa. Nơi đây giam giữ các chiến sĩ cách mạng Việt Nam thời thuộc địa, sau này giam phi công Mỹ, những người gọi nó là “Hanoi Hilton”. Hiện chỉ còn giữ lại một phần; phần còn lại đã thành toà nhà cao tầng từ thập niên 1990.', 'The French built this prison in 1896 on the site of a village of potters — “hoa lo” means fiery furnace. It held Vietnamese revolutionaries under colonial rule, and later American pilots, who nicknamed it the “Hanoi Hilton”. Only a part remains; the rest became a tower block in the 1990s.', 'Vì sao gọi là “Hỏa Lò”? Trước khi có nhà tù, phố này đầy lò nung gốm và làm bếp lò.', 'Why is it called “fiery furnace”? Before the prison, the street was full of kilns making pottery and charcoal stoves.', 'Cổng vòm có dòng chữ tiếng Pháp chụp đẹp nhất từ bên kia đường Hỏa Lò.', 'The arched gate with its French lettering is best shot from across Hoa Lo street.', 'Đây là nơi của đau thương. Tránh tạo dáng đùa cợt trong phòng giam.', 'This is a place of suffering. Avoid posing playfully in the cells.', 'Dòng chữ tiếng Pháp trên cổng là gì?', 'What French words are written above the gate?', 'Maison Centrale', 'Maison Centrale', 'Palais de Justice', 'Palais de Justice', 'Hôtel de Ville', 'Hôtel de Ville', 'Nghĩa là “ngôi nhà trung tâm”.', 'It means “central house”.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('egg-coffee', 'approved', 'hoan-kiem', 'food', 'full', 'Cà phê trứng Giảng', 'Egg coffee at Giang', 'Cà phê Giảng', 21.0331, 105.8547, null, null, array['food','rainy']::text[], array['localFood','indoor']::text[], 25, 35, 45, null, 'butter', 'Lòng đỏ đánh bông trên nền cà phê đậm, ra đời từ năm 1946.', 'Whipped yolk and sugar over strong coffee, invented here in 1946.', 'Năm 1946, sữa tươi ở Hà Nội rất khan hiếm. Ông Nguyễn Văn Giảng, khi ấy pha chế ở khách sạn Metropole, đánh lòng đỏ trứng với đường thành lớp kem sánh rồi rưới lên cà phê đậm. Gia đình ông vẫn giữ quán, nằm cuối một con ngõ hẹp, và ly cà phê được đặt trong bát nước nóng để giữ ấm.', 'In 1946, fresh milk was scarce in Hanoi. Nguyen Van Giang, a bartender at the Metropole hotel, whisked egg yolk with sugar into a thick cream and spooned it over strong coffee. The family still runs the café, hidden at the end of a narrow passage, and serves the cup in a bowl of hot water to keep it warm.', 'Vì sao có bát nước nóng? Kem trứng nguội rất nhanh – nước nóng giữ cho nó ấm và mịn đến ngụm cuối.', 'Why the bowl of hot water? The egg cream cools fast — the water keeps it warm and silky to the last sip.', 'Chụp từ trên xuống bàn gỗ thấp để thấy lớp bọt vàng và chiếc bát cùng lúc.', 'Shoot from above on the low wooden table to catch the golden foam and the bowl together.', 'Gọi đồ ở quầy rồi mới tìm chỗ – lúc đông khách thường ngồi chung bàn.', 'Order at the counter, then find a seat — tables are shared when it’s busy.', 'Vì sao ông Giảng dùng trứng thay cho sữa?', 'Why did Mr. Giang use egg instead of milk?', 'Sữa tươi khan hiếm', 'Fresh milk was scarce', 'Một đầu bếp Pháp yêu cầu', 'A French chef asked for it', 'Trứng là món cung đình', 'Eggs were a royal tradition', 'Đó là năm 1946 – thời buổi khó khăn.', 'It was 1946 — times were hard.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('bun-cha', 'approved', 'hoan-kiem', 'food', 'full', 'Bún chả Hàng Mành', 'Bun cha on Hang Manh', 'Bún chả Hàng Mành', 21.0322, 105.8478, null, null, array['food']::text[], array['localFood','groups']::text[], 35, 60, 80, null, 'brick', 'Chả nướng than hoa, bún rối và bát nước chấm cho cả mâm.', 'Charcoal-grilled pork, fresh noodles, and a dipping bowl for everyone.', 'Bún chả là bữa trưa của người Hà Nội. Chả viên và chả miếng ba chỉ nướng trên than hoa ngay vỉa hè, rồi thả vào bát nước chấm chua ngọt có đu đủ xanh. Bạn gắp bún nguội và rau sống chấm vào bát, từng miếng một. Phố Hàng Mành xưa là phố làm mành tre – “mành” là tấm rèm.', 'Bun cha is Hanoi’s lunch. Pork patties and slices of pork belly are grilled over charcoal on the sidewalk, then dropped into a sweet-and-sour fish-sauce broth with green papaya. You dip cold rice noodles and fresh herbs into the bowl, bite by bite. Hang Manh street was once the street of bamboo blinds — “manh” means blind.', 'Vì sao lại nướng ngay ngoài phố? Khói chính là biển quảng cáo – mùi thơm dẫn khách tới quán.', 'Why grill on the street? The smoke is the advertisement — you follow your nose to the stall.', 'Bắt khoảnh khắc khói bốc lên từ bếp than ở cửa quán.', 'Catch the smoke rising from the charcoal grill at the shop entrance.', 'Cho ớt, tỏi vào bát của mình, đừng cho vào đĩa chung. Giấy ăn thường tính thêm chút tiền.', 'Add chilli and garlic to your own bowl, not the shared plates. Tissues usually cost a little extra.', 'Ăn bún chả thế nào cho đúng?', 'How do you eat bun cha?', 'Gắp bún chấm vào bát nước có chả', 'Dip noodles into the broth with the pork', 'Đổ tất cả vào một bát canh lớn', 'Pour everything into one big soup', 'Ăn hết chả trước, bún sau', 'Eat the pork first, noodles after', 'Hãy nhìn bàn bên cạnh.', 'Watch the table next to you.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('dong-xuan', 'approved', 'hoan-kiem', 'sight', 'full', 'Chợ Đồng Xuân', 'Dong Xuan Market', 'Chợ Đồng Xuân', 21.0381, 105.8497, null, null, array['food','culture','rainy']::text[], array['lively','indoor']::text[], 30, 0, 50, null, 'leaf', 'Chợ có mái lâu đời nhất Hà Nội, phía sau là ngõ ăn vặt.', 'Hanoi''s oldest covered market, with a street-food alley at the back.', 'Được người Pháp mở năm 1889, Đồng Xuân từng là chợ lớn nhất Đông Dương. Người buôn từ các phố nghề trong phố cổ – hàng lụa, hàng bạc, hàng mã, hàng thiếc – đều mang hàng về đây. Trận hỏa hoạn năm 1994 thiêu rụi phần lớn chợ; chợ được xây lại phía sau mặt tiền vòm cũ, và việc buôn sỉ vẫn bắt đầu từ trước khi trời sáng.', 'Opened by the French in 1889, Dong Xuan was the biggest market in Indochina. Traders from the Old Quarter’s craft streets — silk, silver, paper, tin — sold here. A fire destroyed much of it in 1994; it was rebuilt behind the original arched facade, and wholesale trading still starts before sunrise.', 'Vì sao nhiều phố tên “Hàng…”? Mỗi phố chuyên một mặt hàng – và Đồng Xuân gom tất cả về dưới một mái chợ.', 'Why so many streets named “Hang…”? Each street specialised in one good — and Dong Xuan gathered them all under one roof.', 'Đứng bên kia phố Đồng Xuân để lấy trọn mặt tiền vòm và dòng xe máy phía trước.', 'Stand across Dong Xuan street to get the whole arched facade and the motorbike traffic in front.', 'Hỏi trước khi chụp người bán. Mặc cả là bình thường với đồ lưu niệm, không phải với đồ ăn.', 'Ask before photographing sellers. Bargaining is normal for souvenirs, not for food.', 'Đếm số cửa vòm ở mặt tiền chợ. Có bao nhiêu cửa?', 'Count the arched gates on the front of the market. How many are there?', 'Năm', 'Five', 'Ba', 'Three', 'Bảy', 'Seven', 'Cửa lớn nhất ở giữa, mỗi bên hai cửa.', 'The biggest one is in the middle, with two on each side.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('ta-hien', 'approved', 'hoan-kiem', 'sight', 'full', 'Góc phố Tạ Hiện', 'Ta Hien corner', 'Phố Tạ Hiện', 21.0362, 105.8524, null, null, array['food']::text[], array['lively','localFood']::text[], 20, 20, 40, null, 'teal', 'Ghế nhựa nhỏ, bia hơi và phố cổ lướt qua trước mặt.', 'Tiny plastic stools, fresh beer and the Old Quarter going by.', 'Bia hơi là bia nấu trong ngày, giao bằng thùng mỗi sáng và phải bán hết trước đêm. Bia nhẹ, rẻ và uống trên ghế nhựa thấp ngay vỉa hè. Ngã tư Tạ Hiện – Lương Ngọc Quyến nổi tiếng là nơi người Hà Nội và du khách ngồi sát vai nhau.', 'Bia hoi is beer brewed fresh each day, delivered in kegs every morning and meant to be finished by night. It is light, cheap and drunk on low plastic stools right on the pavement. The crossroads of Ta Hien and Luong Ngoc Quyen became famous as the place where locals and travellers sit elbow to elbow.', 'Vì sao ghế lại nhỏ vậy? Dễ xếp chồng, vừa vỉa hè hẹp và dọn đi chỉ trong vài giây.', 'Why such tiny stools? They stack easily, fit narrow pavements and can be cleared in seconds.', 'Chập tối, đứng ở ngã tư khi đèn lồng bật sáng và ghế nhựa tràn ra phố.', 'Early evening, from the crossroads, when the lanterns light up and stools spill into the street.', 'Nâng ly và hô “Một, hai, ba, dô!”. Đã uống bia thì không lái xe.', 'Say “Một, hai, ba, dô!” when toasting. Don’t drink and ride a motorbike.', '“Bia hơi” đặc biệt ở điểm nào?', 'What makes “bia hoi” special?', 'Nấu trong ngày và bán hết trong ngày', 'It’s brewed fresh and sold the same day', 'Được ủ một năm', 'It’s aged for a year', 'Nhập từ Pháp', 'It’s imported from France', 'Thùng bia được chở đến mỗi sáng.', 'Kegs arrive every morning.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('the-huc', 'approved', 'hoan-kiem', 'sight', 'full', 'Cầu Thê Húc lúc hoàng hôn', 'The Huc Bridge at dusk', 'Cầu Thê Húc', 21.0302, 105.8527, null, null, array['photo']::text[], array['free','photo']::text[], 10, 0, 0, null, 'brick', 'Cầu đỏ đẹp nhất khi chụp từ bờ hồ, ngay trước lúc lên đèn.', 'The red bridge photographs best from the shore, just before the lights come on.', 'Cây cầu gỗ cong được Nguyễn Văn Siêu cho dựng năm 1865 để dẫn vào đền Ngọc Sơn. Tên cầu có nghĩa là “nơi đậu ánh sáng ban mai”. Cầu đã được làm lại nhiều lần nhưng vẫn giữ dáng cong màu đỏ xuất hiện trên bưu thiếp Hà Nội hơn một thế kỷ qua.', 'The curved wooden bridge was built in 1865 by Nguyen Van Sieu to lead to Ngoc Son Temple. Its name means “where the morning sunlight rests”. It has been rebuilt several times, but it keeps the same red curve that has appeared on Hanoi postcards for over a century.', 'Vì sao sơn đỏ? Đỏ là màu may mắn và của mặt trời mọc – hợp với cái tên “nơi đậu ánh ban mai”.', 'Why red? Red is the colour of luck and of the rising sun — fitting for “where morning light rests”.', 'Đến trước giờ lên đèn khoảng 20 phút. Chụp từ bờ để dáng cầu in bóng xuống mặt nước.', 'Go 20 minutes before the street lights switch on. Shoot from the shore so the curve reflects in the water.', 'Cầu hẹp – hãy đứng sang một bên khi chụp để người khác đi qua.', 'The bridge is narrow — step aside to take photos so others can pass.', '“Thê Húc” có nghĩa là gì?', 'What does “The Huc” mean?', 'Nơi đậu ánh sáng ban mai', 'Where the morning sunlight rests', 'Lưng rồng', 'The dragon’s back', 'Cầu của sĩ tử', 'The bridge of scholars', 'Hãy nghĩ tới mặt trời lúc sớm mai.', 'Think of the rising sun.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('turtle-tower', 'approved', 'hoan-kiem', 'sight', 'full', 'Góc nhìn Tháp Rùa', 'Turtle Tower view', 'Tháp Rùa', 21.0281, 105.852, null, null, array['photo','history']::text[], array['free','photo']::text[], 10, 0, 0, null, 'leaf', 'Ngọn tháp nhỏ giữa hồ gắn với truyền thuyết trả gươm.', 'A small tower in the lake that carries the legend of the returned sword.', 'Tương truyền sau khi vua Lê Lợi đánh đuổi quân Minh vào thế kỷ 15, một con rùa vàng nổi lên giữa hồ và đòi lại thanh gươm thần đã giúp vua thắng trận. Từ đó hồ mang tên Hoàn Kiếm – “trả gươm”. Ngọn tháp nhỏ trên gò giữa hồ được xây vào cuối thế kỷ 19.', 'Legend says that after King Le Loi drove out the Ming army in the 15th century, a golden turtle rose from this lake and took back the magic sword that had helped him win. The lake has been called Hoan Kiem — “Returned Sword” — ever since. The small tower on the islet was built in the late 19th century.', 'Vì sao lại là rùa? Trong truyền thuyết Việt, rùa là linh vật tượng trưng cho trí tuệ và trường thọ.', 'Why a turtle? In Vietnamese legend the turtle is a sacred messenger of wisdom and long life.', 'Từ bờ tây trên phố Lê Thái Tổ, sáng sớm khi mặt hồ còn phẳng lặng.', 'From the west shore on Le Thai To street, early morning, when the water is still.', 'Tối cuối tuần quanh hồ là phố đi bộ – hãy tận hưởng và giữ hồ sạch.', 'On weekend evenings the lake roads are pedestrian-only — enjoy them, and keep litter out of the water.', 'Trong truyền thuyết, vị vua nào trả gươm?', 'In the legend, which king returned the sword?', 'Lê Lợi', 'Le Loi', 'Lý Thái Tổ', 'Ly Thai To', 'Trần Hưng Đạo', 'Tran Hung Dao', 'Ông đánh quân Minh vào thế kỷ 15.', 'He fought the Ming army in the 1400s.', 1, null, '{}'::text[], 'Nội dung mẫu viết khi dựng giao diện — chưa có nguồn. Cần đối chiếu tư liệu, kiểm giá và kiểm thử thách tại chỗ.'),
  ('national-history-museum', 'approved', 'hoan-kiem', 'sight', 'full', 'Bảo tàng Lịch sử Quốc gia', 'National Museum of Vietnamese History', 'Bảo tàng Lịch sử Quốc gia', 21.024243, 105.859716, '1 Tràng Tiền, Hoàn Kiếm', 'Tu-Su 08:00-12:00,13:30-17:00', array['history','culture','rainy']::text[], array['indoor','history','iconic']::text[], 60, 40, 40, null, 'butter', 'Trống đồng, tượng thần Chăm và cọc Bạch Đằng dưới một mái vòm Đông Dương.', 'Bronze drums, Champa gods and the stakes of Bach Dang under one Indochinese dome.', 'Toà nhà ra đời năm 1932 là Bảo tàng Louis Finot của Trường Viễn Đông Bác cổ. Hai kiến trúc sư Batteur và Hébrard kết hợp mặt bằng kiểu Pháp với mái và chi tiết Việt – phong cách được gọi là ''kiến trúc Đông Dương''. Năm 1958, nơi đây trở thành Bảo tàng Lịch sử Việt Nam. Bên trong, bạn đi từ công cụ thời tiền sử tới trống đồng Đông Sơn, điêu khắc Chăm Pa và những cọc gỗ từng đánh chìm đoàn thuyền giặc trên sông Bạch Đằng.', 'This building began life in 1932 as the Louis Finot Museum of the French School of the Far East. Architects Batteur and Hébrard mixed French plans with Vietnamese roofs and details — the ''Indochinese'' style. In 1958 it became the Museum of Vietnamese History. Inside you walk from prehistoric tools to Dong Son bronze drums, Champa sculpture and the wooden stakes used to sink invading fleets on the Bach Dang river.', 'Vì sao toà nhà Pháp lại có mái giống chùa? Kiến trúc sư muốn một bảo tàng về châu Á phải mang dáng dấp châu Á.', 'Why the pagoda-like roof on a French building? The architects wanted a museum of Asia to look like it belonged in Asia.', 'Lùi sang bên kia đường để lấy trọn sảnh bát giác và mái nhiều tầng trong một khung hình.', 'Step back across the street to fit the octagonal entrance hall and its layered roof in one frame.', 'Đóng cửa thứ Hai. Không dùng đèn flash gần hiện vật; có thể phải gửi túi ở quầy.', 'Closed on Mondays. No flash near the artefacts; bags may need to be left at the counter.', 'Sảnh chính của bảo tàng có hình gì?', 'What shape is the main entrance hall?', 'Bát giác', 'Octagon', 'Hình tròn', 'Circle', 'Hình vuông', 'Square', 'Đếm số cạnh của gian phòng dưới mái vòm.', 'Count the sides of the room under the dome.', 1, 'Q5370414', array['https://vi.wikipedia.org/wiki/Bảo_tàng_Lịch_sử_quốc_gia_(Việt_Nam)','https://www.wikidata.org/wiki/Q5370414']::text[], 'Kiểm tra giá vé hiện tại (40k là ước lượng) và giờ mở cửa. Kiểm tra cọc Bạch Đằng còn trưng bày ở toà này không.'),
  ('hanoi-post-office', 'approved', 'hoan-kiem', 'sight', 'full', 'Bưu điện Bờ Hồ', 'Hanoi Post Office clock', 'Bưu điện Hà Nội', 21.026506, 105.853726, '75 Đinh Tiên Hoàng, Hoàn Kiếm', null, array['history','photo']::text[], array['free','photo','iconic']::text[], 10, 0, 0, null, 'teal', 'Chiếc đồng hồ bên hồ mà người Hà Nội nào cũng từng hẹn nhau dưới chân.', 'The lakeside clock every Hanoian has arranged to meet under.', 'Người Pháp xây toà bưu điện trung tâm Hà Nội ở đây năm 1901, trên phần đất của chùa Báo Ân bị phá. Toà nhà bạn thấy hôm nay được dựng lại vào thập niên 1970: năm tầng, trên đỉnh có chiếc đồng hồ lớn. Đồng hồ và hàng chữ trên mặt tiền đã thành biểu tượng của thành phố – ''hẹn nhau dưới đồng hồ Bưu điện'' là câu nói của nhiều thế hệ người Hà Nội.', 'The French built Hanoi''s central post office here in 1901, on land taken from the Bao An pagoda. The building you see now went up in the 1970s: five storeys with a big clock on top. Its clock and lettering became a symbol of the city — ''meet me under the Post Office clock'' has been said by generations of Hanoians.', 'Vì sao lại đặt ở đây, nhìn ra hồ? Quy hoạch năm 1883 của người Pháp lấy hồ Hoàn Kiếm làm trung tâm mới, và bưu điện là đầu mối liên lạc với cả xứ thuộc địa.', 'Why here, facing the lake? The French plan of 1883 made Hoan Kiem the new centre, and the post office was the link to the rest of the colony.', 'Đứng ở bờ hồ đối diện, lấy chiếc đồng hồ cùng dòng xe trên phố Đinh Tiên Hoàng phía trước.', 'From the lake shore opposite, frame the clock with the traffic of Dinh Tien Hoang in front.', 'Bưu điện vẫn hoạt động – bạn có thể gửi một tấm bưu thiếp về nhà ngay ở quầy bên trong.', 'It is a working post office — you can still send a postcard home from the counter inside.', 'Trên đỉnh toà Bưu điện Bờ Hồ có gì?', 'What sits on top of the Post Office building?', 'Một chiếc đồng hồ lớn', 'A large clock', 'Một tháp chuông', 'A bell tower', 'Một cột ăng-ten', 'A radio mast', 'Nó cho cả bờ hồ biết ai đang đến muộn.', 'It tells everyone at the lake if they are late.', 1, 'Q113457479', array['https://vi.wikipedia.org/wiki/Bưu_điện_Hà_Nội','https://www.wikidata.org/wiki/Q113457479']::text[], 'Xác nhận năm xây lại (tư liệu ghi ''thập niên 1970''). Kiểm tra quầy gửi bưu thiếp cho khách còn phục vụ không.'),
  ('hoa-phong-tower', 'approved', 'hoan-kiem', 'sight', 'full', 'Tháp Hòa Phong', 'Hoa Phong Tower', 'Tháp Hòa Phong', 21.026336, 105.853313, 'Bờ đông hồ Hoàn Kiếm (Đinh Tiên Hoàng)', null, array['history','photo']::text[], array['free','photo','quiet']::text[], 10, 0, 0, null, 'brick', 'Tất cả những gì còn lại của một ngôi chùa 180 gian – ngọn tháp nhỏ bên hồ.', 'All that is left of a 180-bay pagoda — one small tower by the lake.', 'Khoảng năm 1842, Tổng đốc Nguyễn Đăng Giai quyên tiền dân để dựng chùa Báo Ân bên bờ đông hồ – 180 gian, nổi tiếng kiến trúc cầu kỳ. Năm 1888, người Pháp phá bình địa ngôi chùa để xây bưu điện. Chỉ còn ngọn tháp ba tầng phía sau là sót lại. Bốn cửa vòm của tháp mang tên bốn điều báo đáp: Báo Ân, Báo Nghĩa, Báo Đức và Báo Phúc.', 'Around 1842, governor Nguyen Dang Giai raised money from the people to build Bao An pagoda on the east shore of the lake — 180 bays, famous for its elaborate architecture. In 1888 the French levelled it to build the post office. Only this three-storey tower at the back survived. Its four arched doors are named for four kinds of gratitude: Bao An, Bao Nghia, Bao Duc and Bao Phuc.', 'Vì sao hai mặt ghi ''Hòa Phong'' còn hai mặt kia lại ghi ''Báo Thiên tháp''? Ngọn tháp mang nhiều tên – hỏi người Hà Nội, bạn sẽ nghe nhiều cách giải thích.', 'Why do two sides say ''Hoa Phong'' and the other two ''Bao Thien''? The tower carries more than one name — ask a local and you will hear different stories.', 'Chụp từ lối đi ven hồ, lấy mặt nước phía sau tháp, sáng sớm khi đường còn vắng.', 'Shoot from the lakeside path with the water behind the tower, early morning when the path is quiet.', 'Tháp là di tích được bảo vệ – ngắm thôi, đừng trèo.', 'The tower is a protected relic — look, don''t climb.', 'Tầng một của tháp có mấy cửa vòm?', 'How many arched doors does the ground floor have?', 'Bốn', 'Four', 'Hai', 'Two', 'Sáu', 'Six', 'Mỗi hướng một cửa.', 'One for each direction.', 1, 'Q10825843', array['https://vi.wikipedia.org/wiki/Tháp_Hòa_Phong','https://www.wikidata.org/wiki/Q10825843']::text[], 'Kiểm tra tại chỗ chữ ''Báo Thiên tháp'' ở mặt bắc–nam.'),
  ('48-hang-ngang', 'approved', 'hoan-kiem', 'sight', 'full', 'Nhà 48 Hàng Ngang', '48 Hang Ngang — Declaration House', 'Nhà 48 Hàng Ngang', 21.034328, 105.850439, '48 Hàng Ngang, Hoàn Kiếm', null, array['history','culture']::text[], array['history','quiet','indoor']::text[], 20, 0, 10, null, 'brick', 'Căn phòng trên gác nơi bản Tuyên ngôn Độc lập được đánh máy năm 1945.', 'The upstairs room where the Declaration of Independence was typed in 1945.', 'Tháng 8 năm 1945, đây là nhà của ông Trịnh Văn Bô, một nhà tư sản Hà Nội. Chủ tịch Hồ Chí Minh ở trong căn phòng ăn rộng trên gác hai. Bên chiếc bàn vuông nhỏ bọc da xanh màu lá mạ, cạnh chiếc máy chữ mang từ chiến khu về, Người soạn thảo bản Tuyên ngôn Độc lập ngày 26/8. Bản tuyên ngôn được hoàn chỉnh ở số 12 Ngô Quyền và đọc tại Quảng trường Ba Đình ngày 2/9.', 'In August 1945 this was the home of Trinh Van Bo, a Hanoi merchant. Ho Chi Minh stayed in the large first-floor dining room. At a small square table covered in green leather, next to a portable typewriter brought from the resistance base, he drafted the Declaration of Independence on 26 August. It was finished at 12 Ngo Quyen and read in Ba Dinh Square on 2 September.', 'Vì sao lại là nhà của một thương nhân? Ngôi nhà nằm giữa phố cổ đông đúc, nơi một vị khách quan trọng có thể ở mà không gây chú ý.', 'Why a merchant''s house? It sat in the busy Old Quarter, where an important guest could stay unnoticed among the shops.', 'Bên trong, chụp chiếc bàn viết nhỏ sát tường; bên ngoài, mặt tiền hẹp cho thấy nhà phố cổ sâu thế nào.', 'Inside, photograph the small writing table by the wall; outside, the narrow facade shows how deep Old Quarter houses are.', 'Nơi lưu giữ ký ức dân tộc: ăn mặc chỉnh tề, nói nhỏ, không chạm vào đồ đạc.', 'A place of national memory: dress neatly, speak quietly, don''t touch the furniture.', 'Chiếc bàn nơi viết bản Tuyên ngôn được bọc da màu gì?', 'What colour was the table where the Declaration was written?', 'Xanh lá mạ', 'Green', 'Đỏ', 'Red', 'Nâu', 'Brown', 'Màu của mạ non.', 'The colour of young rice shoots.', 1, 'Q10800786', array['https://vi.wikipedia.org/wiki/Nhà_48_Hàng_Ngang','https://www.wikidata.org/wiki/Q10800786']::text[], 'Kiểm tra giờ mở cửa, có thu phí không, và chiếc bàn bọc da xanh có còn trưng bày để người chơi nhìn thấy không (thử thách phụ thuộc vào chi tiết này).'),
  ('opera-house', 'approved', 'hoan-kiem', 'sight', 'full', 'Nhà hát Lớn Hà Nội', 'Hanoi Opera House', 'Nhà hát Lớn', 21.024193, 105.857825, '1A Tràng Tiền, Hoàn Kiếm', null, array['culture','history','photo']::text[], array['iconic','photo','free']::text[], 15, 0, 0, null, 'butter', 'Một ''Opéra Paris'' thu nhỏ, nơi Quốc hội đầu tiên của Việt Nam nhóm họp.', 'A little Paris opera house, where Vietnam''s first National Assembly met.', 'Được người Pháp xây từ năm 1901 đến 1911, Nhà hát Lớn mô phỏng Nhà hát Opéra Garnier ở Paris, nhỏ hơn và dùng vật liệu hợp khí hậu nhiệt đới. Nơi đây không chỉ là nhà hát: năm 1946, Quốc hội đầu tiên của nước Việt Nam độc lập đã họp tại đây và thông qua bản Hiến pháp đầu tiên. Đợt trùng tu 1995–1997 trả lại vẻ đẹp xưa, và đến nay đây vẫn là sân khấu hàng đầu của Hà Nội.', 'Built by the French between 1901 and 1911, the Opera House follows the Palais Garnier in Paris, on a smaller scale and with materials suited to the tropics. It was more than a theatre: in 1946 the first National Assembly of independent Vietnam met here and passed the country''s first constitution. A 1995–1997 restoration brought back its original look, and it is still one of Hanoi''s main stages.', 'Vì sao lại xây nhà hát opera ở thuộc địa? Với người Pháp, một nhà hát lớn là dấu hiệu cho thấy Hà Nội là thủ phủ, chứ không phải đồn tiền tiêu.', 'Why build an opera house in a colony? For the French, a grand theatre was a sign that Hanoi was a capital, not an outpost.', 'Quảng trường Cách mạng Tháng Tám phía trước cho bạn trọn mặt tiền đối xứng – đẹp nhất lúc nắng chiều.', 'The square in front (August Revolution Square) gives the full symmetric facade — best in late afternoon light.', 'Chỉ vào bên trong khi có vé biểu diễn hoặc vé tham quan có hướng dẫn. Buổi diễn tối nên ăn mặc lịch sự.', 'Inside only with a performance or guided-tour ticket. Dress smart for evening shows.', 'Nhà hát Lớn được xây theo mẫu nhà hát nào?', 'Which theatre was it modelled on?', 'Opéra Garnier, Paris', 'Palais Garnier, Paris', 'La Scala, Milan', 'La Scala, Milan', 'Bolshoi, Moskva', 'Bolshoi, Moscow', 'Người xây là người Pháp.', 'The builders were French.', 1, 'Q1186043', array['https://vi.wikipedia.org/wiki/Nhà_hát_Lớn_Hà_Nội','https://www.wikidata.org/wiki/Q1186043']::text[], 'Giá 0 là chỉ ngắm bên ngoài. Kiểm tra giá tour tham quan bên trong và lịch diễn nếu muốn thêm.'),
  ('o-quan-chuong', 'approved', 'hoan-kiem', 'sight', 'full', 'Ô Quan Chưởng', 'O Quan Chuong Gate', 'Ô Quan Chưởng', 21.037331, 105.852198, 'Phố Ô Quan Chưởng (đầu phố Hàng Chiếu)', null, array['history','photo']::text[], array['free','history','photo']::text[], 10, 0, 0, null, 'leaf', 'Cửa ô cuối cùng còn lại của thành Thăng Long xưa, vẫn còn vọng lâu.', 'The last surviving gate of the old city wall, still with its watchtower.', 'Hà Nội xưa được bao bởi một vòng thành đất với nhiều cửa ô. Cửa phía Đông này – cửa Đông Hà – xây năm 1749, dựng lại năm 1817, và là cửa ô duy nhất còn sót lại. Lính gác trên vọng lâu kiểm soát con đường ra sông Hồng. Trên tường còn tấm bia đá do Tổng đốc Hoàng Diệu cho đặt năm 1881, cấm lính gác sách nhiễu người dân qua lại.', 'Old Hanoi was ringed by an earthen wall pierced by many gates (ô). This eastern one, Dong Ha gate, was built in 1749 and rebuilt in 1817 — and it is the only one left. Guards in the watchtower controlled the road to the Red River. On the wall hangs a stone stele placed in 1881 by governor Hoang Dieu, forbidding guards from harassing people passing through.', 'Vì sao gọi là ''Quan Chưởng''? Tương truyền năm 1873 một vị chưởng cơ cùng quân sĩ đã giữ cửa ô này đến người cuối cùng – câu chuyện đến nay vẫn chưa được sử liệu xác minh.', 'Why ''Quan Chuong''? Legend says a commander (chưởng cơ) and his men defended this gate to the last in 1873 — a story historians still haven''t confirmed.', 'Đứng giữa phố lúc sáng sớm để lấy trọn ba cửa vòm và vọng lâu.', 'Stand in the middle of the street early in the morning to frame all three arches and the watchtower.', 'Xe cộ vẫn đi qua cửa ô – hãy đứng sang bên khi chụp ảnh.', 'Traffic still passes through the gate — step to the side for photos.', 'Trên cửa chính có ba chữ Hán. Đó là chữ gì?', 'Above the main arch are three Chinese characters. What do they say?', 'Đông Hà môn (東河門)', 'Dong Ha Mon (東河門)', 'Quan Chưởng môn', 'Quan Chuong Mon', 'Thăng Long môn', 'Thang Long Mon', 'Đó là tên cũ của cửa – sông nằm ở phía đông.', 'It''s the gate''s old name — the river is on its east side.', 1, 'Q10839688', array['https://vi.wikipedia.org/wiki/Ô_Quan_Chưởng','https://www.wikidata.org/wiki/Q10839688']::text[], 'Số cửa ô của Hà Nội xưa: các nguồn ghi khác nhau (16 hoặc 21) — đã bỏ con số khỏi câu chuyện, cần xác minh nếu muốn thêm lại. Kiểm tra tấm bia năm 1881 còn đọc được tại chỗ.'),
  ('quan-su-pagoda', 'approved', 'hoan-kiem', 'sight', 'full', 'Chùa Quán Sứ', 'Quan Su Pagoda', 'Chùa Quán Sứ', 21.024453, 105.845415, '73–79 Quán Sứ, Hoàn Kiếm', null, array['culture','history']::text[], array['free','cultural','quiet']::text[], 20, 0, 0, null, 'butter', 'Ngôi chùa ra đời bên nhà khách đón sứ thần.', 'A pagoda born next to a guesthouse for foreign envoys.', 'Thế kỷ 15, sứ thần Chiêm Thành, Ai Lao thường sang Thăng Long triều cống. Triều Lê dựng một toà nhà để đón tiếp – gọi là Quán Sứ – và vì các sứ thần đều sùng đạo Phật nên dựng thêm ngôi chùa bên cạnh. Toà quán sứ nay không còn, nhưng ngôi chùa vẫn ở lại. Năm 1934, chùa trở thành trụ sở của Tổng hội Phật giáo Bắc Kỳ, và năm 1942 được xây lại như ngày nay.', 'In the 15th century, envoys from Champa and Laos came to Thang Long to pay tribute. The Le court built a guesthouse — the Quan Su, ''envoys'' lodge'' — and, because the envoys were devout Buddhists, a pagoda beside it. The lodge is long gone but the pagoda stayed. In 1934 it became the headquarters of the northern Buddhist association, and in 1942 it was rebuilt in the form you see today.', 'Vì sao lại dựng chùa cho người nước ngoài? Để sứ thần được lễ Phật như ở quê nhà là một cử chỉ tôn trọng – ngoại giao bằng lòng hiếu khách.', 'Why build a pagoda for foreigners? Letting envoys pray as they did at home was a gesture of respect — diplomacy by hospitality.', 'Từ sân chùa, chụp hướng lên 11 bậc thềm dẫn vào chính điện – đẹp nhất khi khói hương bắt nắng.', 'From the courtyard, look up the 11 steps to the main hall — best when incense smoke catches the light.', 'Chùa đang hoạt động: mặc kín vai và gối, bỏ giày ở nơi có biển báo, giữ yên lặng khi có tụng kinh.', 'An active pagoda: cover shoulders and knees, take off shoes where signs ask, and keep quiet during chanting.', 'Tên ''Quán Sứ'' bắt nguồn từ đâu?', 'Where does the name ''Quan Su'' come from?', 'Nhà khách đón sứ thần', 'A lodge for foreign envoys', 'Một chợ bán quạt', 'A market for fans', 'Tên một nhà sư', 'The name of a monk', 'Hãy nghĩ tới những vị khách từ Chiêm Thành, Ai Lao.', 'Think of visitors from Champa and Laos.', 1, 'Q7273080', array['https://vi.wikipedia.org/wiki/Chùa_Quán_Sứ','https://www.wikidata.org/wiki/Q7273080']::text[], 'Cách hồ ~900 m. Kiểm tra số bậc thềm (tư liệu ghi 11).'),
  ('imperial-citadel', 'approved', 'hoan-kiem', 'sight', 'full', 'Hoàng thành Thăng Long', 'Imperial Citadel of Thang Long', 'Hoàng thành Thăng Long', 21.036289, 105.840442, '19C Hoàng Diệu, Ba Đình', 'Tu-Su 08:00-17:00', array['history','culture','photo']::text[], array['iconic','history','groups']::text[], 60, 30, 70, null, 'leaf', 'Mười ba thế kỷ quyền lực chồng lên nhau trong một di sản thế giới UNESCO.', 'Thirteen centuries of power, layered in one UNESCO World Heritage site.', 'Từ thế kỷ 7 đến triều Nguyễn, đây là trung tâm quyền lực của châu thổ sông Hồng – các triều Lý, Trần, Lê dựng cung điện chồng lên nhau trên cùng một vùng đất. Năm 2010, đúng dịp Thăng Long tròn 1000 năm, UNESCO công nhận khu trung tâm là Di sản Văn hoá Thế giới vì 13 thế kỷ lịch sử liên tục. Hãy đi qua Đoan Môn, rồi nhìn xuống các hố khai quật, nơi nền móng của nhiều triều đại nằm chồng lên nhau.', 'From the 7th century to the Nguyen dynasty, this was the seat of power in the Red River delta — Ly, Tran and Le kings built palace upon palace on the same ground. In 2010, the year Hanoi turned 1,000, UNESCO listed the central sector as World Heritage for its 13 centuries of continuous history. Walk through Doan Mon gate, then look down into the excavations where foundations from different dynasties lie stacked on top of each other.', 'Vì sao 1.300 năm vẫn xây trên cùng một chỗ? Vì phong thuỷ, vì dòng sông, và vì quan niệm quyền lực phải ở nơi quyền lực vốn đã ở.', 'Why build on the same spot for 1,300 years? Feng shui, the river and the idea that power belongs where power has always been.', 'Đoan Môn nhìn từ sân trong, với năm cửa vòm, là khung hình kinh điển.', 'Doan Mon gate from the inner courtyard, with its five arched doors, is the classic shot.', 'Khu di tích rộng và ít bóng mát – mang nước và mũ. Cách hồ khoảng 1,3 km: chặng hợp để đi Grab hoặc xe máy.', 'Big site with little shade — bring water and a hat. About 1.3 km from the lake: a good leg for a Grab or motorbike.', 'UNESCO công nhận Hoàng thành là Di sản Thế giới năm nào?', 'In which year did UNESCO list the citadel as World Heritage?', '2010', '2010', '2000', '2000', '1999', '1999', 'Cùng năm Hà Nội mừng đại lễ 1000 năm.', 'The same year Hanoi celebrated 1,000 years.', 1, 'Q206219', array['https://vi.wikipedia.org/wiki/Hoàng_thành_Thăng_Long','https://www.wikidata.org/wiki/Q206219']::text[], 'Giá vé 30–70k là ước lượng rộng, cần kiểm tra. Kiểm tra số cửa của Đoan Môn trước khi dùng trong góc chụp. Nằm ngoài bán kính đi bộ quanh hồ.'),
  ('ba-kieu-temple', 'approved', 'hoan-kiem', 'sight', 'full', 'Đền Bà Kiệu', 'Ba Kieu Temple', 'Đền Bà Kiệu', 21.031107, 105.853457, 'Đinh Tiên Hoàng, Hoàn Kiếm (đối diện cổng đền Ngọc Sơn)', null, array['culture','history']::text[], array['free','quiet','cultural']::text[], 15, 0, 0, null, 'brick', 'Ngôi đền bị một đại lộ thời Pháp cắt làm đôi.', 'A temple cut in two by a French boulevard.', 'Được dựng vào khoảng những năm 1620 thời Lê, đền Bà Kiệu thờ ba vị nữ thần, đứng đầu là Công chúa Liễu Hạnh – một trong Tứ bất tử của tín ngưỡng dân gian Việt. Năm 1891, người Pháp lấy một phần đất của đền để mở đại lộ Francis Garnier – nay là phố Đinh Tiên Hoàng. Con đường chia ngôi đền làm đôi: cổng tam quan ở lại bên bờ hồ, còn nhà đại bái và hậu cung nằm bên kia đường.', 'Built in the 1620s under the Le dynasty, Ba Kieu honours three goddesses, led by Princess Lieu Hanh, one of the Four Immortals of Vietnamese folk belief. In 1891 the French took part of its land to build Boulevard Francis Garnier — today''s Dinh Tien Hoang street. The road split the temple: the gate stayed on the lake side, while the main halls ended up across the street.', 'Vì sao cổng đền lại nằm bên kia đường? Vì con đường đến sau ngôi đền tới 270 năm.', 'Why is the gate on the other side of the road? Because the road came 270 years after the temple.', 'Đứng ở cổng bên bờ hồ, chụp sang dãy nhà đền bên kia đường để thấy rõ sự chia đôi.', 'From the lakeside gate, frame the temple halls across the street to show the split.', 'Nơi thờ Mẫu – ăn mặc kín đáo và hỏi trước khi chụp ảnh các nghi lễ.', 'A place of Mother Goddess worship — dress modestly and ask before photographing ceremonies.', 'Con phố nào cắt đôi khu đền?', 'Which street cuts the temple in two?', 'Đinh Tiên Hoàng', 'Dinh Tien Hoang', 'Hàng Khay', 'Hang Khay', 'Lê Thái Tổ', 'Le Thai To', 'Con phố chạy dọc bờ đông của hồ.', 'It runs along the east shore of the lake.', 1, 'Q16481078', array['https://vi.wikipedia.org/wiki/Đền_Bà_Kiệu','https://www.wikidata.org/wiki/Q16481078']::text[], 'Kiểm tra giờ mở cửa; đền nhỏ, có lúc đóng.'),
  ('ly-thai-to-park', 'approved', 'hoan-kiem', 'sight', 'full', 'Vườn hoa Lý Thái Tổ', 'Ly Thai To Square', 'Vườn hoa Lý Thái Tổ', 21.027452, 105.854748, 'Đinh Tiên Hoàng, Hoàn Kiếm', '24/7', array['history','photo']::text[], array['free','lively','photo']::text[], 10, 0, 0, null, 'teal', 'Người khai sinh Thăng Long, bằng đồng, dõi về phía hồ.', 'The founder of Thang Long, in bronze, watching over the lake.', 'Thời Pháp, vườn hoa mang tên Paul Bert và có tượng đồng của ông cho đến năm 1945, khi Hà Nội đổi tên phố và vườn hoa theo tên các danh nhân Việt. Năm 2004, tượng đài vua Lý Thái Tổ – người dời đô về Thăng Long năm 1010 – được dựng tại đây: đúc đồng liền khối, cao 10,1 m, nặng 32 tấn cả bệ. Sáng sớm, quảng trường rộn ràng người tập dưỡng sinh, khiêu vũ.', 'Under the French this garden was named after Paul Bert and held his bronze statue until 1945, when Hanoi renamed its streets after Vietnamese heroes. In 2004 a 10-metre bronze statue of King Ly Thai To — who moved the capital to Thang Long in 1010 — was raised here, cast in one piece, 32 tonnes with its base. In the early morning the square fills with dancers and tai chi groups.', 'Vì sao phố quanh đây mang tên các danh tướng – Lê Lai, Đinh Lễ, Nguyễn Xí? Họ là tướng của Lê Lợi, người gắn với truyền thuyết của chính mặt hồ này.', 'Why do so many streets here carry generals'' names — Le Lai, Dinh Le, Nguyen Xi? They fought with Le Loi, whose story belongs to this lake.', 'Đến lúc 6 giờ sáng: tượng đài, người tập thể dục và mặt hồ trong nắng dịu.', 'Come at 6 am: the statue, the dancers and the lake in soft light.', 'Người tập buổi sáng rất hiếu khách – cứ tham gia, nhưng đừng quay cận mặt người khác khi chưa hỏi.', 'Morning exercisers welcome visitors — join in, but don''t film people up close without asking.', 'Tượng vua Lý Thái Tổ quay mặt về hướng nào?', 'Which way does the statue of King Ly Thai To face?', 'Về phía hồ Hoàn Kiếm', 'Towards Hoan Kiem Lake', 'Về phía sông Hồng', 'Towards the Red River', 'Về phía phố cổ', 'Towards the Old Quarter', 'Đứng trước tượng và nhìn theo hướng nhà vua.', 'Stand in front of him and look where he looks.', 1, 'Q25418011', array['https://vi.wikipedia.org/wiki/Vườn_hoa_Chí_Linh','https://www.wikidata.org/wiki/Q25418011']::text[], null),
  ('cua-bac-church', 'approved', 'hoan-kiem', 'sight', 'full', 'Nhà thờ Cửa Bắc', 'Cua Bac Church', 'Nhà thờ Cửa Bắc', 21.041453, 105.840506, '56 Phan Đình Phùng, Ba Đình', null, array['culture','photo']::text[], array['free','photo','quiet']::text[], 15, 0, 0, null, 'teal', 'Ngôi nhà thờ vừa Âu vừa Á – một cách có chủ ý.', 'A church that looks both European and Asian — on purpose.', 'Được khởi công năm 1925 bởi cha xứ người Pháp Antoine Depaulis (Cố Hương) theo bản vẽ của kiến trúc sư Ernest Hébrard, nhà thờ Cửa Bắc được khánh thành năm 1930. Tên gọi lấy từ Cửa Bắc của thành Thăng Long cũ ngay gần đó. Hébrard phá vỡ lối đối xứng quen thuộc: tháp chuông cao lệch một bên cân với mái vòm ở giữa, mái hiên rộng và bố cục hợp khí hậu nhiệt đới – một ví dụ tiêu biểu của kiến trúc Đông Dương.', 'Started in 1925 by French priest Antoine Depaulis to plans by architect Ernest Hébrard, Cua Bac church was consecrated in 1930. It is named after the North Gate of the old Thang Long citadel nearby. Hébrard broke the usual symmetry: a tall bell tower on one side balances a central dome, with wide eaves and a layout suited to the tropics — a key example of the Indochinese style.', 'Vì sao không đối xứng như Nhà thờ Lớn? Hébrard muốn một nhà thờ hoà hợp với châu Á, thay vì sao chép từ Pháp.', 'Why isn''t it symmetrical like St Joseph''s? Hébrard wanted a church that felt at home in Asia rather than copied from France.', 'Từ bên kia phố Phan Đình Phùng, chụp tháp chuông và mái vòm cùng hàng cây cổ thụ.', 'From across Phan Dinh Phung street, shoot the bell tower and dome together under the old trees.', 'Giáo xứ vẫn sinh hoạt: vào nhẹ nhàng ngoài giờ lễ. Cách hồ khoảng 1,9 km – nên đi xe máy hoặc Grab.', 'An active parish: enter quietly outside Mass times. About 1.9 km from the lake — better by bike or Grab.', 'Tháp chuông nằm ở đâu so với mái vòm?', 'Where is the bell tower compared with the dome?', 'Lệch sang một bên', 'Off to one side', 'Ngay trên đỉnh mái vòm', 'Directly on top of it', 'Hai tháp, mỗi bên một tháp', 'Two towers, one on each side', 'Nhà thờ này nổi tiếng vì không đối xứng.', 'This church is famously not symmetrical.', 1, 'Q1088224', array['https://vi.wikipedia.org/wiki/Nhà_thờ_Cửa_Bắc','https://www.wikidata.org/wiki/Q1088224']::text[], 'Wikipedia ghi khánh thành 1/2/1930, Wikidata ghi 1932 — cần xác minh. Nằm xa hồ.'),
  ('dien-hong-garden', 'approved', 'hoan-kiem', 'sight', 'full', 'Vườn hoa Diên Hồng', 'Dien Hong Garden', 'Vườn hoa Diên Hồng', 21.026481, 105.856013, 'Ngô Quyền – Lý Thái Tổ, Hoàn Kiếm', '24/7', array['photo','history']::text[], array['free','photo','quiet']::text[], 10, 0, 0, null, 'leaf', 'Đài phun nước cổ nhất Hà Nội trong khu vườn nhỏ mà người dân gọi là ''vườn hoa Con Cóc''.', 'Hanoi''s oldest fountain, in a small French garden locals call ''Toad Garden''.', 'Khoảng năm 1899, người Pháp xây khu vườn này để tưởng niệm Léon Chavassieux, một phó Toàn quyền Đông Dương, và đặt tên theo ông. Sau này vườn được đổi tên thành vườn hoa Diên Hồng. Đài phun nước ở đây được xem là cổ nhất Hà Nội và sau hơn trăm năm vẫn giữ nét xưa. Khu vườn nằm giữa khách sạn Metropole và Ngân hàng Nhà nước, là góc chụp ảnh cưới quen thuộc.', 'Around 1899 the French built this garden as a memorial to Léon Chavassieux, a deputy governor-general of Indochina, and named it after him. After independence it became Dien Hong garden. Its fountain is said to be the oldest in Hanoi and, after more than a century, still keeps its old look. It sits between the Metropole hotel and the State Bank, and is a favourite spot for wedding photos.', 'Vì sao gọi là ''vườn hoa Con Cóc''? Hãy nhìn kỹ đài phun nước – người dân đặt tên theo chính thứ họ thấy ở đó.', 'Why ''Toad Garden''? Look closely at the fountain — locals named the garden after what they saw there.', 'Chụp góc thấp từ lối đi, đài phun nước ở tiền cảnh, những toà nhà Pháp màu vàng phía sau.', 'Low angle from the path, with the fountain in front and the yellow French buildings behind.', 'Các cặp đôi hay chụp ảnh cưới bên đài phun nước – chờ lượt và tránh lọt vào khung hình của họ.', 'Wedding shoots often use the fountain — wait your turn and stay out of their frame.', 'Người Hà Nội gọi vui vườn hoa này là gì?', 'What nickname do Hanoians give this garden?', 'Vườn hoa Con Cóc', 'Toad Garden', 'Vườn hoa Con Rùa', 'Turtle Garden', 'Vườn hoa Con Rồng', 'Dragon Garden', 'Một con vật nhỏ thích nước và mưa.', 'A small animal that loves water and rain.', 1, 'Q10834022', array['https://vi.wikipedia.org/wiki/Vườn_hoa_Diên_Hồng','https://www.wikidata.org/wiki/Q10834022']::text[], 'Xác minh tại chỗ đài phun nước có tượng cóc (lý do tên gọi) trước khi dùng câu ''Vì sao?''.'),
